agent-browser eval "new Promise(resolve => {
  const btn = document.querySelector(\"[data-testid='like-1']\");
  const likes = document.querySelector(\"[data-testid='likes-1']\");
  const before = likes.textContent;
  btn.click();
  let results = [];
  let start = Date.now();
  let interval = setInterval(() => {
    results.push({ time: Date.now() - start, value: likes.textContent });
    if (Date.now() - start > 200) {
      clearInterval(interval);
      resolve(JSON.stringify({ before, results }));
    }
  }, 10);
})"

